/**
 * The page break of a document — the line alone with `\pagebreak`.
 *
 * The PDF and the .docx generated by the app already treat that line as a break. The
 * TWO ends that show the document on the screen were missing: the Markdown canvas, which
 * wrote `\pagebreak` as text, and the .docx viewer, which drew the
 * whole file on a single sheet. Both read from here so they do not diverge.
 */

/**
 * What stays in the converted HTML in place of each explicit break of the .docx.
 *
 * Mammoth reads the break and writes NOTHING for it; without a mark the panel would
 * have no way to know where a page ends. The conversion puts the mark in its own
 * paragraph, so the cut does not split any tag in half.
 */
export const DOCX_PAGE_BREAK_MARK = '@@orbit:pagebreak@@'

const PAGE_BREAK_LINE = /^[ \t]*\\pagebreak[ \t]*$/m

/**
 * The Markdown in pages, without the instruction lines. Without any `\pagebreak`
 * it returns a single item — the document is one page, as it always was.
 */
export function splitOnPageBreaks(markdown: string): string[] {
  return markdown.split(PAGE_BREAK_LINE).map((part) => part.trim())
}

/** The HTML of the .docx in sheets. Without an explicit break, a single sheet. */
export function splitDocxPages(html: string): string[] {
  const marker = new RegExp(`<p[^>]*>\\s*${DOCX_PAGE_BREAK_MARK}\\s*</p>`)
  return html.split(marker).map((part) => part.trim())
}
